local function C_6()
local script = G2L["6"];
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local TextChatService = game:GetService("TextChatService")
	local plr = Players.LocalPlayer

	-- Define your custom client-sided spawn position here
	local CUSTOM_SPAWN_CFRAME = CFrame.new(0, 100, 0)
	local VOID_HEIGHT = -100 

	local diedInVoid = false
	local spamTeleportActive = false
	local spamEndTime = 0

	-- Function to handle the actual high-frequency spam teleportation loop
	local function triggerSpamTeleport()
		if spamTeleportActive then 
			spamEndTime = os.clock() + 5 -- Extend duration if triggered again
			return 
		end

		spamTeleportActive = true
		spamEndTime = os.clock() + 5

		local connection
		connection = RunService.RenderStepped:Connect(function()
			if os.clock() > spamEndTime then
				spamTeleportActive = false
				connection:Disconnect()
				return
			end

			-- Spam teleport the current character's HumanoidRootPart every frame
			if plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
				plr.Character.HumanoidRootPart.CFrame = CUSTOM_SPAWN_CFRAME
				-- Zero out velocity so you don't accumulate falling momentum when it finishes
				plr.Character.HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
			end
		end)
	end

	-- Check chat content for trigger words
	local function checkChatMessage(messageText)
		local lowerMsg = string.lower(messageText)
		if string.find(lowerMsg, "mapseed") or string.find(lowerMsg, "maptide") then
			triggerSpamTeleport()
		end
	end

	-- 1. Listen for new TextChatService (Modern Roblox Chat)
	TextChatService.MessageReceived:Connect(function(textChatMessage)
		if textChatMessage.Text then
			checkChatMessage(textChatMessage.Text)
		end
	end)

	-- 2. Listen for Legacy Chat System (Older/Custom Chat frameworks)
	local function hookPlayerChat(otherPlayer)
		otherPlayer.Chatted:Connect(function(msg)
			checkChatMessage(msg)
		end)
	end

	Players.PlayerAdded:Connect(hookPlayerChat)
	for _, p in ipairs(Players:GetPlayers()) do
		hookPlayerChat(p)
	end

	-- Void Death Spawn Handling
	local function trackCharacter(char)
		local hrp = char:WaitForChild("HumanoidRootPart", 5)
		local humanoid = char:WaitForChild("Humanoid", 5)
		if not hrp or not humanoid then return end

		if diedInVoid then
			hrp.CFrame = CUSTOM_SPAWN_CFRAME
			diedInVoid = false 
		end

		humanoid.Died:Connect(function()
			if hrp.Position.Y <= VOID_HEIGHT then
				diedInVoid = true
			else
				diedInVoid = false
			end
		end)
	end

	plr.CharacterAdded:Connect(trackCharacter)
	if plr.Character then
		task.spawn(trackCharacter, plr.Character)
	end

end;
