local function C_8b()
local script = G2L["8b"];
	local plr = game.Players.LocalPlayer
	local playerGui = plr:WaitForChild("PlayerGui")

	local button = script.Parent
	local activeValue = button:WaitForChild("AuraActive")

	local function runAuraWork()
		local char = plr.Character
		if not char then return end

		local hum = char:FindFirstChildOfClass("Humanoid")
		local dtool = plr.Backpack:FindFirstChild("Delete") or char:FindFirstChild("Delete")
		local aura = workspace:FindFirstChild("DeleteAura")

		if not dtool or not hum or not aura then return end

		local overlapParams = OverlapParams.new()
		overlapParams.FilterType = Enum.RaycastFilterType.Exclude
		overlapParams.FilterDescendantsInstances = {char, aura}

		local touchedParts = workspace:GetPartsInPart(aura, overlapParams)

		for _, v in ipairs(touchedParts) do
			if not activeValue.Value then break end

			local isInBricks = (v.Parent == workspace:FindFirstChild("Bricks")) or 
				(v.Parent and v.Parent.Parent == workspace:FindFirstChild("Bricks"))

			if isInBricks and v.Name == "Brick" then
				local previouslyholding = char:FindFirstChildOfClass("Tool")

				hum:EquipTool(dtool)
				if dtool:FindFirstChild("Script") and dtool.Script:FindFirstChild("Event") then
					dtool.Script.Event:FireServer(v, v.Position)
					dtool:Activate()
				end

				if previouslyholding and previouslyholding.Parent == plr.Backpack then
					hum:EquipTool(previouslyholding)
				end

				break
			end
		end
	end

	activeValue.Changed:Connect(function(isRunning)
		if isRunning then
			task.spawn(function()
				while activeValue.Value do
					task.wait()
					runAuraWork()
				end
			end)
		end
